{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "resolution_minutes",
  "per_column": [
    {
      "name": "ticket_category",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Category (bug vs how-to vs incident) is knowable at intake and plausibly drives resolution time; a legitimate feature outside the focus."
    },
    {
      "name": "product_area",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Which component the ticket touches is available up front and different areas have systematically different resolution durations."
    },
    {
      "name": "reported_severity_signal",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Severity as reported in the description is an intake-time signal correlated with effort; not a restatement of resolution_minutes."
    },
    {
      "name": "business_deadline_pressure",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Stated urgency/deadline is knowable at report time and can influence prioritization and thus resolution time."
    },
    {
      "name": "affected_user_scope",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Scope of impact (single user vs whole tenant) is derivable from the ticket text and predictive of triage effort and duration."
    },
    {
      "name": "environment_scope",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether prod vs staging is affected is an intake-time attribute plausibly linked to handling speed and complexity."
    },
    {
      "name": "root_cause_type",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Root cause is typically established during/after investigation, not at intake; it co-occurs with the resolution process and risks leaking the outcome."
    },
    {
      "name": "regression_after_change",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether the issue followed a recent change can be stated in the report and is a plausible pre-resolution predictor; borderline but often knowable at intake."
    },
    {
      "name": "reproducibility",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Reproducibility (consistent vs intermittent) is a diagnostic property described early and strongly correlated with debugging effort/time."
    }
  ],
  "n_predictors": 8,
  "predictive_utility": 0.72,
  "rationale": "Most added columns are semantically distinct intake-time signals (category, product area, severity, urgency, scope, environment, reproducibility) that lie outside resolution_minutes and plausibly carry predictive signal beyond the original priority/channel/agent columns. root_cause_type is flagged as leakage because it is usually determined through the resolution process itself rather than known before the outcome. As a set they offer strong, non-redundant predictive leverage, so utility is high but not maximal due to one leaking column and some overlap with existing priority."
}

